#define EXPOSURE 1.0
//basic exposure value

const float gamma = 2.2;

vec3 tone(vec3 color){	
	mat3 m1 = mat3(
        0.59719, 0.07600, 0.02840,
        0.35458, 0.90834, 0.13383,
        0.04823, 0.01566, 0.83777
	);
	mat3 m2 = mat3(
        1.60475, -0.10208, -0.00327,
        -0.53108,  1.10813, -0.07276,
        -0.07367, -0.00605,  1.07602
	);
	vec3 v = m1 * color;    
	vec3 a = v * (v + 0.0245786) - 0.000090537;
	vec3 b = v * (0.983729 * v + 0.4329510) + 0.238081;
	return pow(clamp(m2 * (a / b), 0.0, 1.0), vec3(1.0 / gamma));
}

void mainImage (out vec4 fragColor, in vec2 fragCoord) {
	vec2 uv = (fragCoord / iResolution.xy);

    vec4 col = texture(iChannel0, uv);
    col.rgb /= col.w;

    col.rgb = tone(col.rgb * EXPOSURE);

	fragColor = vec4(col.rgb, 1.0);
}

#define NOBLERAY

#define SAMPLES 25
#define SCATTER_EVENTS 5

const int odpoints = 8;

const float sundeg = 0.5;

const float ozone = 1.0;

const float planetrad = 6371e3;
const float atmoheight = 110e3;

const vec2 scaleheights = vec2(8.4, 1.25);

const float atmorad = planetrad + atmoheight;
const float atmolowerlim = planetrad;

float rphase(float c) {
    return  3.0 * (1.0 + c * c) / 16.0 / pi;
}

float mphase (float c, float wl) {
    float g = 0.76;

    float e = 1.0;
    for (int i = 0; i < 8; i++) {
        float gFromE = 1.0 / e - 2.0 / log(2.0 * e + 1.0) + 1.0;
        float deriv = 4.0 / ((2.0 * e + 1.0) * log(2.0 * e + 1.0) * log(2.0 * e + 1.0)) - 1.0 / (e * e);
        if (abs(deriv) < 0.00000001) break;
        e = e - (gFromE - g) / deriv;
    }

    return e / (2.0 * pi * (e * (1.0 - c) + 1.0) * log(2.0 * e + 1.0));
}

vec2 raymiedens (in float h) {
    return exp(-h / scaleheights);
}

//From Jessie
float ozonedens (in float h) {
    float o1 = 25.0 *     exp(( 0.0 - h) /   8.0) * 0.5;
    float o2 = 30.0 * pow(exp((18.0 - h) /  80.0), h - 18.0);
    float o3 = 75.0 * pow(exp((25.3 - h) /  35.0), h - 25.3);
    float o4 = 50.0 * pow(exp((30.0 - h) / 150.0), h - 30.0);
    return (o1 + o2 + o3 + o4) / 134.628;
}

vec3 dens2 (float height) {
    height = (max(height, planetrad) - planetrad) / 1000.0;
    vec2 raymie = raymiedens(height);
    float ozone = ozonedens(height);

    return vec3(raymie, ozone);
}

float lighttrans (vec3 ro, vec3 rd, float wl) {
    float dist = dot(ro, rd);
    dist = sqrt(dist * dist + atmorad * atmorad - dot(ro, ro)) - dist;
    float t = dist / float(odpoints);
    vec3 step = rd * t;
    ro += step * 0.5;

    vec3 sum = vec3(0.0);
    for (int i = 0; i < odpoints; i++, ro += step) {
        float height = length(ro);
        sum += dens2(height);
    }

    float scattero = ozonefunc(wl) * ozone;

    float scatterr = BetaR(wl);
    #ifdef NOBLERAY
    scatterr = rayleighCrossSection(wl, 1.00029);
    #endif

    float scatterm = BetaM(wl);

    float od = (scatterr * t * sum.x) + (scatterm * t * sum.y) + (scattero * t * sum.z);
    float trans = exp(-od);
    if (isnan(trans)) trans = 0.0;
    if (isinf(trans)) trans = 1.0;

    return trans;
}

float lighttrans2 (vec3 ro, vec3 rd, float dist, float wl) {
    float t = dist / float(odpoints);
    vec3 step = rd * t;
    ro += step * 0.5;

    vec3 sum = vec3(0.0);
    for (int i = 0; i < odpoints; i++, ro += step) {
        float height = length(ro);
        sum += dens2(height);
    }

    float scattero = ozonefunc(wl) * ozone;

    float scatterr = BetaR(wl);
    #ifdef NOBLERAY
    scatterr = rayleighCrossSection(wl, 1.00029);
    #endif

    float scatterm = BetaM(wl);

    float od = (scatterr * t * sum.x) + (scatterm * t * sum.y) + (scattero * t * sum.z);
    float trans = exp(-od);
    if (isnan(trans)) trans = 0.0;
    if (isinf(trans)) trans = 1.0;

    return trans;
}

float trace (vec3 ro, vec3 rd) {
    vec2 atmo = RSI(ro, rd, vec4(vec3(0.0), atmorad));
    vec2 plan = RSI(ro, rd, vec4(vec3(0.0), atmolowerlim));

    bool atmoi = atmo.y >= 0.0;
    bool plani = plan.x >= 0.0;

    vec2 idk = vec2((plani && plan.x < 0.0) ? plan.y : max(atmo.x, 0.0), (plani && plan.x > 0.0) ? plan.x : atmo.y);

    return length(idk.y - idk.x);
}

float pt (vec3 ro, vec3 rd, vec3 lrd, float intens, float col, uint rng, float wl) {
    float through = 1.0;
    float scattering = 0.0;

    float scatterr = BetaR(wl);
    #ifdef NOBLERAY
    scatterr = rayleighCrossSection(wl, 1.00029);
    #endif

    float scatterm = BetaM(wl);

    vec3 p = ro;

    float trans = lighttrans2(ro, rd, trace(ro, rd), wl);

    for (int i = 0; i < SCATTER_EVENTS; i++) {
        float t = trace(p, rd);
        float dist = t * randF(rng);

        float od = lighttrans2(p, rd, dist, wl);

        p = p + rd * dist;

        vec3 mass = dens2(length(p));
        if (mass.x > 1e35) break;
        if (mass.y > 1e35) break;
        if (mass.z > 1e35) break;
        if (any(isnan(mass))) mass = vec3(0.0);

        vec3 newDir = randV(rng);

        float mu = dot(rd, newDir);

        float rayphase = rphase(mu) * 4.0 * pi;
        float miephase = mphase(mu, wl) * 4.0 * pi;

        float mu2 = dot(rd, lrd);

        float rayphase2 = rphase(mu2) * 4.0 * pi;
        float miephase2 = mphase(mu2, wl) * 4.0 * pi;

        scattering += through * (scatterr * mass.x * rayphase2 + scatterm * mass.y * miephase2) * od * lighttrans(p, lrd, wl) * t * intens;
        through *= (scatterr * mass.x * rayphase + scatterm * mass.y * miephase) * od * t;

        rd = newDir;
    }

    return scattering + col * trans;
}

float skypt (vec3 ro, vec3 rd, vec3 sunrd, float col, uint rng, float wl) {
    ro.y += planetrad;

    float sunintens = plancks(wl, 5800.0);
    float sun = dot(rd, sunrd) > cos(radians(sundeg)) ? sunintens : col;

    vec3 sampledsunrd = coneDir(sunrd, rng, radians(sundeg));

    return pt(ro, rd, sampledsunrd, sunintens * 2.0 * pi * (1.0 - cos(radians(sundeg))), sun, rng, wl);
}

void mainImage (out vec4 fragColor, in vec2 fragCoord) {
	vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec2 m = (iMouse.xy / iResolution.xy) * 2.0 - 1.0;
    m.x *= iResolution.x / iResolution.y;


    float fov = 90.0;
	vec3 ro = vec3(0.0, 100.0, 0.0);
    float camdist = 1.0 / tan(fov * 0.5 * pi / 180.0);
    vec3 rt = vec3(uv, camdist) + ro + vec3(0.0, 0.0, 0.0);
	vec3 rd = normalize(rt - ro);

    //ro.y += 50000.0;

    vec3 sunrd = normalize(vec3(0.0, cos(iTime * 0.25), sin(iTime * 0.25)));
    sunrd = normalize(vec3(0.0, 0.2, 10.0));

    if (iMouse.x > 0.0) {
        sunrd = normalize(vec3(m.x, m.y, 1.0));
    }

    uint rng = uint(iResolution.x * iResolution.y) * uint(iFrame) + uint(fragCoord.x + fragCoord.y * iResolution.x);

    vec3 col = vec3(0.0);
    for (int i = 0; i < SAMPLES - min(iFrame, 0); i++) {
        float wl = 390.0 + 440.0 * randF(rng);
        float new = skypt(ro, rd, sunrd, 0.0, rng, wl);
        col += (wltoxyz(wl) * new) * xyztorgb;
    }
    col /= float(SAMPLES);  

    vec4 lastframe = texture(iChannel0, fragCoord/iResolution.xy);

    if (iFrame == 0 || iMouse.z > 0.0 || any(isnan(lastframe.rgb))) {
        lastframe = vec4(0.0);
    }

    float temp = lastframe.w;

    vec3 newcol = lastframe.rgb + col;
    temp += 1.0;

	fragColor = vec4(newcol, temp);
}
